/**
 * M07 lecture 7.E — Playwright CLI on Tubi (cost model)
 *
 * The same Tubi-Movies task as 02-claude-mcp-result.spec.ts, but generated by
 * constraining Claude Code to the **Playwright CLI** workflow (commands +
 * on-disk artifacts) instead of the MCP browser tools that stream live page
 * state into the model on every step.
 *
 * The headline of 7.E: the resulting test is *comparable in quality* to the
 * MCP version — but it cost roughly a quarter of the tokens to generate
 * (~27K vs ~114K; ~$0.08 vs ~$0.34 on a current Sonnet model). See
 * docs/m07-cost-comparison.md for the measured numbers and methodology.
 *
 * The lesson is NOT "CLI wins." It's the rubric: reach for the CLI when the
 * agent is executing a plan you already understand; reach for MCP when it has
 * to reason about live page state. Same destination here, so cost is the
 * tiebreaker — which is exactly the point.
 *
 * Compare against ./02-claude-mcp-result.spec.ts (same task, MCP-generated).
 */

import { test, expect } from '../../shared/fixtures/index.js';
import { skipInHeadless, skipOnMobile } from '../../shared/test-guards.js';

test(
  'Movies page is reachable via menubar (CLI-generated)',
  { tag: '@desktop-menubar' },
  async ({ tubiHome, page }) => {
    skipOnMobile('Desktop menubar navigation');
    await tubiHome.goto();
    await tubiHome.browseMenuItem('Movies');
    await expect(page).toHaveURL(/\/movies/);
    await expect(tubiHome.categoryNav).toBeVisible();
  },
);

test('Movies page renders at least 12 content tiles after lazy-load (CLI-generated)', async ({
  tubiHome,
}) => {
  skipOnMobile('Movies menubar navigation is desktop-only');
  skipInHeadless('Tubi lazy-loaded tiles need headed mode');
  await tubiHome.goto();
  await tubiHome.browseMenuItem('Movies');
  await tubiHome.triggerLazyLoad();
  expect(await tubiHome.contentTiles.count()).toBeGreaterThanOrEqual(12);
});
